-- PostgreSQL baseline migration. Docker's first boot uses SQLAlchemy metadata for zero-config demo setup.
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'citizen', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS incidents (id SERIAL PRIMARY KEY, title VARCHAR(200) NOT NULL, hazard VARCHAR(50) NOT NULL, severity INTEGER NOT NULL, risk_score INTEGER NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'reported', lat DOUBLE PRECISION NOT NULL, lng DOUBLE PRECISION NOT NULL, address VARCHAR(250) NOT NULL DEFAULT '', assigned_to VARCHAR(100) NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reports (id SERIAL PRIMARY KEY, incident_id INTEGER NOT NULL REFERENCES incidents(id), user_id INTEGER NOT NULL REFERENCES users(id), text TEXT NOT NULL, image_url VARCHAR(300) NOT NULL DEFAULT '', voice_text TEXT NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS events (id SERIAL PRIMARY KEY, incident_id INTEGER NOT NULL REFERENCES incidents(id), actor VARCHAR(100) NOT NULL, action VARCHAR(100) NOT NULL, note TEXT NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
